/*!40000 ALTER TABLE `blogs` DISABLE KEYS */;
INSERT INTO `blogs` VALUES (1,'Hướng dẫn chăm sóc hoa hồng','<h2 class=\"content-detail-sapo sm-sapo-mb-0\" style=\"list-style: none; margin-top: 1.25rem; margin-bottom: 1.25rem; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: 1rem; line-height: 1.625rem; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; color: rgb(64, 64, 64);\"><br></h2><div class=\"maincontent main-content\" id=\"maincontent\" style=\"list-style: none; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: 1rem; line-height: 1.75rem; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; color: rgb(80, 80, 80);\"><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Thường trực Ban Chỉ đạo Trung ương về phòng, chống tham nhũng, lãng phí, tiêu cực thống nhất đưa 4 vụ án, vụ việc có dấu hiệu lãng phí vào diện theo dõi, chỉ đạo là dự án Tòa nhà Trung tâm điều hành và giao dịch thương mại, Tổng công ty Xi măng Việt Nam (Vicem); dự án Thủy điện Hồi Xuân, tỉnh Thanh Hóa; dự án xây dựng trụ sở Bộ Ngoại giao; Tiểu dự án 2 (Lim - Phả Lại), thuộc dự án tuyến đường sắt Yên Viên - Phả Lại - Hạ Long - Cái Lân.&nbsp;</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Đây đều là các công trình kéo dài nhiều năm, chưa hoàn thành, chỉ hoàn thành một phần nhỏ và có dấu hiệu lãng phí nghiêm trọng.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Vậy, những dự án này có quy mô đầu tư như thế nào?</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\"><span style=\"list-style: none; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Toà nhà làm việc của Bộ Ngoại giao chỉ một phần đưa vào hoạt động</span></p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\"><a href=\"https://vietnamnet.vn/tru-so-4000-ty-cham-tien-do-bo-ngoai-giao-xin-co-che-dac-thu-547528.html\" style=\"list-style: none; text-decoration-line: underline; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: inherit; line-height: 1.25rem; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; color: rgb(45, 103, 173); text-underline-offset: 1px;\">Dự án đầu tư xây dựng trụ sở Bộ Ngoại giao</a>&nbsp;do Ban quản lý dự án - Bộ Ngoại giao làm chủ đầu tư, được phê duyệt từ tháng 7/2009 với tổng vốn 3.484 tỷ đồng.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Đây là dự án thuộc nhóm A, công trình cấp đặc biệt. Diện tích xây dựng 16.282m2, tổng diện tích sàn 126.282m2 (không kể diện tích ngoài trời như khu vực để xe, thảm cỏ, khu thể thao giải trí và đường giao thông nội bộ).&nbsp;</p><figure class=\"image vnn-content-image\" data-vnnembed=\"true\" data-vnnembedtype=\"image\" data-vnnembedid=\"00ZUHQ\" style=\"list-style: none; margin: 20px auto; border-style: initial; border-color: initial; border-image: initial; font-style: italic; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 14px; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; display: block; color: rgb(111, 111, 111); text-align: center; width: 760px;\"><picture style=\"list-style: none;\"><source data-srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=0&amp;s=Cs9feAmu8yNJ59-rg7cFZA\" media=\"(max-width: 1023px)\" srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=0&amp;s=Cs9feAmu8yNJ59-rg7cFZA\" style=\"list-style: none;\"><img src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-original=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=0&amp;s=Cs9feAmu8yNJ59-rg7cFZA\" class=\" lazy-loaded\" data-srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=0&amp;s=Cs9feAmu8yNJ59-rg7cFZA\" alt=\"W-tru so bo ngoai giao.jpg\" data-thumb-small-src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=260&amp;s=rOf8QUBffSkOVtfI3b6wdw\" data-thumb-src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=260&amp;s=rOf8QUBffSkOVtfI3b6wdw\" data-lg-id=\"7ca28988-8ead-422b-8c86-505e4df4f2c8\" srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/w-tru-so-bo-ngoai-giao-53096.jpg?width=0&amp;s=Cs9feAmu8yNJ59-rg7cFZA\" style=\"list-style: none; margin-right: auto; margin-left: auto; border-style: initial; border-color: initial; border-image: initial; font: inherit; width: 760px; display: block;\"></picture><figcaption style=\"list-style: none; margin-top: 10px; padding-right: 1.875rem; padding-left: 1.875rem; border-style: initial; border-color: initial; border-image: initial; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: 0.9375rem; line-height: 1.4; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; display: block; width: 760px;\">Trụ sở mới của Bộ Ngoại giao được xây dựng tại phường Mễ Trì (quận Nam Từ Liêm, Hà Nội). Ảnh: Hoàng Hà</figcaption></figure><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Do nhiều nguyên nhân, như biến động giá cả vật tư, vật liệu xây dựng; tiền lương nhân công, tỷ giá... nên tháng 7/2014, Bộ Ngoại giao đã ban hành Quyết định phê duyệt tổng mức đầu tư điều chỉnh dự án giai đoạn 1 lên gần 4.023 tỷ đồng.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Trong văn bản cho ý kiến về việc xin cơ chế đặc thù để giải quyết các vướng mắc của dự án trụ sở Bộ Ngoại giao, Bộ Xây dựng cho rằng, cơ chế đặc thù cho dự án mới chỉ để xử lý tình huống, chưa thể giải quyết triệt để, tháo gỡ các khó khăn vướng mắc hiện nay của dự án.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">“Nếu áp dụng một cách cứng nhắc các cơ chế này như đề xuất tại tờ trình cho toàn bộ các hợp đồng thì sẽ dẫn đến bất cập trong quản lý dự án, quản lý chi phí đầu tư xây dựng, gây lãng phí, thất thoát tài sản, giảm hiệu quả đầu tư” - văn bản của Bộ Xây dựng nêu.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\"><span style=\"list-style: none; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Dự án đường sắt Yên Viên - Phả Lại - Hạ Long - Cái Lân cả thập kỷ \"đứng hình\"</span></p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Những cây cầu cụt này thuộc&nbsp;<a href=\"https://vietnamnet.vn/ly-do-du-an-duong-sat-yen-vien-ha-long-cham-tien-do-17-nam-2107025.html\" style=\"list-style: none; text-decoration-line: underline; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: inherit; line-height: 1.25rem; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; color: rgb(45, 103, 173); text-underline-offset: 1px;\">dự án đường sắt Yên Viên - Phả Lại - Hạ Long - Cái Lân</a>&nbsp;có tổng mức đầu tư 7.665 tỷ đồng.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Dự án được khởi công năm 2005, dự kiến hoàn thành đầu năm 2012 nhưng đến năm 2011 dự án buộc phải giãn tiến độ.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Dự án này bị tạm dừng theo Nghị quyết số 11 ngày 24/2/2011 của Chính phủ về những giải pháp chủ yếu tập trung kiềm chế lạm phát, ổn định kinh tế vĩ mô, bảo đảm an sinh xã hội. Tuy nhiên, một số công trình đã được xây dựng, trong đó có những cầu đường sắt nêu trên. Tại những cây cầu phần móng trụ trơ trọi, sắt thép han gỉ.</p><figure class=\"image vnn-content-image\" data-vnnembed=\"true\" data-vnnembedtype=\"image\" data-vnnembedid=\"00ZUG6\" style=\"list-style: none; margin: 20px auto; border-style: initial; border-color: initial; border-image: initial; font-style: italic; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 14px; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; display: block; color: rgb(111, 111, 111); text-align: center; width: 760px;\"><picture style=\"list-style: none;\"><source data-srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=0&amp;s=TIazgfJnowoVXgcAPOJYdg\" media=\"(max-width: 1023px)\" srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=0&amp;s=TIazgfJnowoVXgcAPOJYdg\" style=\"list-style: none;\"><img src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-original=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=0&amp;s=TIazgfJnowoVXgcAPOJYdg\" class=\" lazy-loaded\" data-srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=0&amp;s=TIazgfJnowoVXgcAPOJYdg\" alt=\"cau vuot duong sat\" data-thumb-small-src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=260&amp;s=09PxTAK9bZUwasn-6VzyNg\" data-thumb-src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=260&amp;s=09PxTAK9bZUwasn-6VzyNg\" data-lg-id=\"1e0f2f2a-0614-413e-9512-3efdc4692d01\" srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/cau-vuot-duong-sat-53098.png?width=0&amp;s=TIazgfJnowoVXgcAPOJYdg\" style=\"list-style: none; margin-right: auto; margin-left: auto; border-style: initial; border-color: initial; border-image: initial; font: inherit; width: 760px; display: block;\"></picture><figcaption style=\"list-style: none; margin-top: 10px; padding-right: 1.875rem; padding-left: 1.875rem; border-style: initial; border-color: initial; border-image: initial; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: 0.9375rem; line-height: 1.4; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; display: block; width: 760px;\">Những cây cầu xây dựng 20 năm chưa xong. Ảnh: Bảo Khánh</figcaption></figure><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Đại diện Sở GTVT tỉnh Bắc Ninh cho biết, các cây cầu này chạy qua địa bàn tỉnh Bắc Ninh nhưng thuộc dự án do Bộ Giao thông Vận tải làm chủ đầu tư, triển khai từ nhiều năm nay.&nbsp;</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Bộ Giao thông Vận tải (nay là Bộ Xây dựng) đang nghiên cứu lập điều chỉnh báo cáo nghiên cứu tiền khả thi dự án làm cơ sở triển khai đầu tư trong giai đoạn 2026-2030.&nbsp;</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\"><span style=\"list-style: none; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Thủy điện hơn 3.300 tỷ ở Thanh Hóa cả thập kỷ chưa xong</span></p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Được khởi công từ năm 2010, dự án thủy điện Hồi Xuân (Quan Hóa, Thanh Hóa) có tổng mức đầu tư hơn 3.320 tỷ đồng, công suất 102 MW, bao gồm ba tổ máy với sản lượng điện trung bình hàng năm hơn 432 triệu Kwh. Dự án do Công ty CP Đầu tư và Xây dựng Điện Hồi Xuân Vneco làm chủ đầu tư.</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Theo kế hoạch, tháng 10/2012, thủy điện Hồi Xuân sẽ chặn dòng lần một, cuối năm 2013 chặn dòng lần hai, đến giữa năm 2014 thì tích nước hồ chứa và phát điện tổ máy số một vào tháng 9 cùng năm.&nbsp;</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Dự án được Bộ Tài chính cấp bảo lãnh cho khoản vay vốn nước ngoài với số tiền trị giá 125 triệu USD vào năm 2015.&nbsp;</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Tuy nhiên, từ năm 2014 đến năm 2018, dự án chững lại, chỉ làm cầm chừng. Từ năm 2018 dự án “đắp chiếu” do thiếu vốn.&nbsp;</p><figure class=\"image vnn-content-image\" data-vnnembed=\"true\" data-vnnembedtype=\"image\" data-vnnembedid=\"00ZUG5\" style=\"list-style: none; margin: 20px auto; border-style: initial; border-color: initial; border-image: initial; font-style: italic; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 14px; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; display: block; color: rgb(111, 111, 111); text-align: center; width: 760px;\"><picture style=\"list-style: none;\"><source data-srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=0&amp;s=5_dZcU3fqAKGB_LD3Qunmw\" media=\"(max-width: 1023px)\" srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=0&amp;s=5_dZcU3fqAKGB_LD3Qunmw\" style=\"list-style: none;\"><img src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-original=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=0&amp;s=5_dZcU3fqAKGB_LD3Qunmw\" class=\" lazy-loaded\" data-srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=0&amp;s=5_dZcU3fqAKGB_LD3Qunmw\" alt=\"thuy dien hoi xuan\" data-thumb-small-src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=260&amp;s=O-HqF809AhVxDJdB0KEH9Q\" data-thumb-src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=260&amp;s=O-HqF809AhVxDJdB0KEH9Q\" data-lg-id=\"3585a4c9-2d16-4128-b740-836faa090ff8\" srcset=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2025/3/26/thuy-dien-hoi-xuan-53099.png?width=0&amp;s=5_dZcU3fqAKGB_LD3Qunmw\" style=\"list-style: none; margin-right: auto; margin-left: auto; border-style: initial; border-color: initial; border-image: initial; font: inherit; width: 760px; display: block;\"></picture><figcaption style=\"list-style: none; margin-top: 10px; padding-right: 1.875rem; padding-left: 1.875rem; border-style: initial; border-color: initial; border-image: initial; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: 0.9375rem; line-height: 1.4; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; display: block; width: 760px;\">Dự án thủy điện Hồi Xuân bỏ hoang. Ảnh: Lê Dương</figcaption></figure><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Theo lãnh đạo huyện Quan Hóa, vùng lòng hồ dự án thuỷ điện Hồi Xuân có hơn 655ha đất bị ảnh hưởng, thuộc hai huyện Mai Châu (Hòa Bình) và huyện Quan Hoá (Thanh Hoá). Gần 1.900 hộ dân ở hai địa phương này bị tác động, trong đó khoảng 500 hộ phải tái định cư đến nơi ở mới.&nbsp;</p><p style=\"list-style: none; margin-top: 1em; margin-bottom: 0px; border-style: initial; border-color: initial; border-image: initial; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; line-height: inherit; font-family: arial; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\">Trước thực trạng trên, UBND tỉnh Thanh Hóa đã nhiều lần đề xuất các bộ, ngành sớm có giải pháp tháo gỡ để dự án tái khởi động, để người dân ổn định đời sống, sản xuất.<br style=\"list-style: none;\"><span style=\"list-style: none; border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\"></span></p><div><br></div></div>',1,'published','2025-03-02 05:39:15','2025-04-07 21:51:40'),(2,'Cách trồng hoa lan nở quanh năm','<p>Hoa lan cần điều kiện đặc biệt...<img src=\"data:image/jpeg;base64,\" data-filename=\"Lan Hồ Điệp.jpg\" style=\"width: 736px;\"></p>',2,'published','2025-03-02 05:39:15','2025-04-07 21:51:41'),(3,'Làm sao để cây xương rồng không bị úng','<p>Xương rồng dễ bị úng nước nếu...</p><p><img src=\"data:image/jpeg;base64,\" data-filename=\"Xxương rồng.jpg\" style=\"width: 736px;\"><br></p>',3,'published','2025-03-02 05:39:15','2025-04-07 21:51:44'),(4,'Kinh nghiệm chọn đất trồng rau sạch','<p>Đất là yếu tố quan trọng...</p><p><img src=\"data:image/jpeg;base64,\" data-filename=\"đất.jpg\" style=\"width: 736px;\"><br></p>',NULL,'published','2025-03-02 05:39:15','2025-04-07 21:51:46'),(5,'Công thức pha đất trồng hoa ly','<p>Hoa ly cần loại đất giàu dinh dưỡng...</p><p><br></p><p><img src=\"data:image/jpeg;base64,\" data-filename=\"Hoa Ly Vàng.jpg\" style=\"width: 736px;\"><br></p>',NULL,'published','2025-03-02 05:39:15','2025-03-22 17:09:59'),(6,'Tổng hợp các giống hoa tulip đẹp','<p>Tulip có nhiều màu sắc đa dạng...</p><p><img src=\"data:image/jpeg;base64,\" data-filename=\"Tulip Đỏ.jpg\" style=\"width: 556px;\"><br></p>',1,'published','2025-03-02 05:39:15','2025-04-07 21:51:47'),(7,'Hướng dẫn trồng hoa cúc đúng cách','<p>Hoa cúc dễ trồng nhưng...</p><p><img src=\"data:image/jpeg;base64,\" data-filename=\"Cúc Trắng.jpg\" style=\"width: 736px;\"><br></p>',2,'published','2025-03-02 05:39:15','2025-03-22 17:10:20');
INSERT INTO `blogs` VALUES (8,'Cách tưới nước cho sen đá','<p>Sen đá không cần quá nhiều nước...</p><p><img src=\"data:image/jpeg;base64,\" data-filename=\"sen đá.jpg\" style=\"width: 675px;\"><br></p>',3,'published','2025-03-02 05:39:15','2025-03-22 17:10:46'),(9,'Những loại hoa dễ trồng tại nhà','Một số loài hoa như...',NULL,'published','2025-03-02 05:39:15','2025-03-02 05:39:15'),(10,'Bí quyết giữ hoa tươi lâu sau khi cắt','Muốn hoa tươi lâu, cần...',NULL,'published','2025-03-02 05:39:15','2025-04-07 21:51:50'),(11,'Lợi ích của cây xanh trong nhà','Cây xanh giúp lọc không khí...',1,'published','2025-03-02 05:39:15','2025-03-02 05:39:15'),(12,'Cách chăm sóc cây kim tiền','Cây kim tiền là loại cây phong thủy...',2,'published','2025-03-02 05:39:15','2025-03-02 05:39:15'),(13,'Top 10 loài cây giúp thanh lọc không khí sạch','Một số cây như lưỡi hổ...',3,'published','2025-03-02 05:39:15','2025-04-08 01:48:26'),(14,'Hướng dẫn chọn chậu cây phù hợp nhất','Việc chọn chậu cây phù hợp giúp...',NULL,'published','2025-03-02 05:39:15','2025-04-08 01:47:04'),(15,'Cách làm phân bón hữu cơ tại nhà','Phân bón hữu cơ giúp cây phát triển...',NULL,'published','2025-03-02 05:39:15','2025-03-02 05:39:15'),(16,'Hướng dẫn làm vườn trên sân thượng','Vườn trên sân thượng đang là xu hướng...',1,'published','2025-03-02 05:39:15','2025-04-07 14:13:52'),(17,'Những lỗi thường gặp khi trồng cây cảnh','Nhiều người mắc sai lầm khi...',2,'published','2025-03-02 05:39:15','2025-03-02 05:39:15'),(18,'Cách chọn giống hoa phù hợp theo mùa','Mỗi mùa có loại hoa phù hợp riêng...',3,'published','2025-03-02 05:39:15','2025-03-02 05:39:15'),(19,'Hướng dẫn bảo dưỡng cây cảnh nội thất','Cây nội thất cần chăm sóc đúng cách nhất...',NULL,'published','2025-03-02 05:39:15','2025-04-08 02:10:20'),(20,'Mẹo trồng cây không cần quá nhiều đất','Một số loại cây có thể trồng trong môi trường ít đất...',NULL,'published','2025-03-02 05:39:15','2025-04-08 01:54:23');
