INSERT INTO `categories` VALUES (1,'Hoa Hồng','Hoa hồng biểu tượng của tình yêu và sự lãng mạn nhất.',1,'2025-03-02 03:20:59','2025-04-08 01:17:15',0,15),(2,'Hoa Cúc','Hoa cúc mang ý nghĩa trường thọ và sự bền vững nhất.',1,'2025-03-02 03:20:59','2025-04-08 01:18:00',0,14),(3,'Hoa Lan','Hoa lan thể hiện sự sang trọng, quý phái.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(4,'Hoa Ly','Hoa ly có hương thơm quyến rũ, biểu tượng cho sự tinh khiết.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(5,'Hoa Sen','Hoa sen đại diện cho sự thanh khiết và cao quý.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(6,'Hoa Đào','Hoa đào mang ý nghĩa may mắn, thịnh vượng.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(7,'Hoa Mai','Hoa mai vàng tượng trưng cho sự giàu sang, phú quý.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(8,'Hoa Tulip','Hoa tulip tượng trưng cho sự hoàn hảo và tình yêu.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(9,'Hoa Hướng Dương','Hoa hướng dương luôn hướng về mặt trời, thể hiện sự trung thành.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(10,'Hoa Bỉ Ngạn','Hoa bỉ ngạn mang ý nghĩa của sự chia ly và ký ức.',1,'2025-03-02 03:20:59','2025-04-07 15:31:12',0,13),(13,'Hoa cưới','Hoa cầm tay cô dâu\r\n\r\nHoa cài áo chú rể\r\n\r\nHoa trang trí xe cưới\r\n\r\nHoa trang trí tiệc cưới',1,'2025-03-22 13:57:27','2025-04-07 15:31:12',1,NULL),(14,'Hoa sự kiện','Hoa khai trương\r\n\r\nHoa hội nghị, hội thảo\r\n\r\nHoa trang trí sân khấu\r\n\r\nHoa tiệc sinh nhật\r\n\r\n',1,'2025-03-22 13:57:36','2025-04-07 15:31:12',1,NULL),(15,'Hoa chúc mừng','Hoa mừng khai trương\r\n\r\nHoa mừng tốt nghiệp\r\n\r\nHoa chúc mừng thăng chức\r\n\r\nHoa chúc mừng kỷ niệm',1,'2025-03-22 13:58:58','2025-04-07 15:31:12',1,NULL),(16,'Hoa chia buồn','Hoa viếng tang\r\n\r\nHoa vòng hoa đám tang\r\n\r\nHoa kệ chia buồn',1,'2025-03-22 13:59:09','2025-04-07 15:31:12',1,NULL),(17,'Hoa trang trí nhà cửa','Hoa bàn ăn\r\n\r\nHoa phòng khách\r\n\r\nHoa ban công, sân vườn',1,'2025-03-22 13:59:34','2025-04-07 15:31:12',1,NULL),(18,'Hoa nghệ thuật','Hoa hộp gỗ, hộp giấy\r\n\r\nHoa bó nghệ thuật\r\n\r\nHoa lẵng cao cấp cao',1,'2025-03-22 13:59:46','2025-04-08 01:14:08',1,NULL),(21,'Hoa tươi','Hoa tươi',1,'2025-04-07 21:24:22','2025-04-08 01:13:41',1,21),(23,'Hoa nhập khẩu','Hoa nhập khẩu',1,'2025-04-08 01:35:42','2025-04-08 02:08:20',1,23);
