INSERT INTO `products` VALUES (2,'Hoa Hồng','Hoa Hồng tươi, màu sắc rực rỡ ',88000.00,784,'uploads/products/1742650136107_hoa hồng.jpg',1,'2025-03-02 03:20:59','2025-04-08 02:12:38'),(3,'Hoa Cúc','Hoa Cúc tươi, màu sắc rực rỡ',73000.00,1364,'uploads/products/1742650149286_hoa cúc.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:29:09'),(4,'Hoa Lan','Hoa Lan tươi, màu sắc rực rỡ',92000.00,965,'uploads/products/1742650159750_hoa lan.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:29:20'),(5,'Hoa Ly','Hoa Ly tươi, màu sắc rực rỡ',46700.00,778,'uploads/products/1742650339479_hoa ly.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:32:19'),(6,'Hoa Sen','Hoa sen đại diện cho sự thanh khiết và cao quý.',120000.00,8,'uploads/products/1742650326557_hoa sen.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:32:07'),(7,'Hoa Đào','Hoa đào mang ý nghĩa may mắn, thịnh vượng.',180000.00,6,'uploads/products/1742650308441_hoa đào.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:31:48'),(8,'Hoa Mai','Hoa mai vàng tượng trưng cho sự giàu sang, phú quý.',250000.00,10,'uploads/products/1742650295519_Mai Vàng Tết.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:31:36'),(9,'Hoa Tulip','Hoa Tulip tươi, màu sắc rực rỡ',56000.00,1201,'uploads/products/1742650271318_Hoa Tulip.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:31:11'),(10,'Hoa Hướng Dương','Hoa Hướng Dương tươi, màu sắc rực rỡ',23500.00,1278,'uploads/products/1742650233741_hướng dương.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:30:34'),(11,'Hoa Bỉ Ngạn','Hoa bỉ ngạn mang ý nghĩa của sự chia ly và ký ức.',130000.00,7,'uploads/products/1742650200317_Bỉ Ngạn.jpg',1,'2025-03-02 03:20:59','2025-03-22 20:30:00'),(55,'Hoa Hồng Đỏ','Hoa hồng đỏ tượng trưng cho tình yêu cháy bỏng.',150000.00,20,'uploads/products/1742650218442_Hồng Đỏ.jpg',1,'2025-03-04 10:00:00','2025-03-22 20:30:18'),(56,'Hoa Cúc Trắng','Hoa cúc trắng biểu tượng của sự thuần khiết.',60000.00,25,'uploads/products/1742650125096_Cúc Trắng.jpg',1,'2025-03-04 10:05:00','2025-03-22 20:28:45'),(57,'Hoa Lan Hồ Điệp','Hoa lan hồ điệp biểu trưng cho sự thanh cao, quý phái.',220000.00,18,'uploads/products/1742650115939_Lan Hồ Điệp.jpg',1,'2025-03-04 10:10:00','2025-03-22 20:28:36'),(58,'Hoa Ly Vàng','Hoa ly vàng là loài hoa mang vẻ đẹp sang trọng, tinh tế và rực rỡ. Những cánh hoa lớn, sắc vàng tươi sáng cùng hương thơm quyến rũ giúp hoa ly trở thành tâm điểm nổi bật trong mọi không gian. Hoa ly vàng không chỉ cuốn hút về hình thức mà còn mang ý nghĩa sâu sắc về sự thịnh vượng, thành công, lòng biết ơn và niềm vui trọn vẹn.\r\n\r\nLoài hoa này thường được sử dụng trong các dịp lễ, chúc mừng hoặc trang trí nhà cửa, không chỉ để tô điểm không gian mà còn gửi gắm lời chúc may mắn và vượng khí đến người nhận.',160000.00,15,'uploads/products/1742650093178_Hoa Ly Vàng.jpg',1,'2025-03-04 10:15:00','2025-03-22 21:09:49'),(59,'Hoa Sen Trắng','Hoa sen trắng là biểu tượng cao quý trong văn hóa phương Đông, đặc biệt gắn liền với sự thuần khiết, thanh cao và tâm hồn trong sáng. Những cánh sen trắng tinh khôi, mềm mại vươn lên từ bùn đất nhưng vẫn tỏa hương thơm nhẹ nhàng, thể hiện vẻ đẹp thanh tịnh, thoát tục và ý chí kiên cường.\r\n\r\nHoa sen trắng thường được sử dụng trong không gian thiền tịnh, trang trí lễ cưới hoặc làm quà tặng mang ý nghĩa tinh thần sâu sắc. Trong phong thủy và tâm linh, sen trắng còn là biểu tượng của sự giác ngộ, an lạc và trí tuệ.',130000.00,30,'uploads/products/1742650076756_Sen Trắng.jpg',1,'2025-03-04 10:20:00','2025-03-22 21:09:32'),(60,'Hoa Đào Phú Quý','Hoa đào phú quý là biểu tượng đặc trưng của mùa xuân miền Bắc Việt Nam, mang theo sắc hồng tươi thắm và không khí ấm áp của những ngày đầu năm mới. Những cánh đào mềm mại, duyên dáng tượng trưng cho sự sum vầy, thịnh vượng, phú quý và khởi đầu tốt lành.\r\n\r\nHoa đào không chỉ mang vẻ đẹp dịu dàng, thanh tao mà còn là lời chúc năm mới an khang, hạnh phúc và thành công. Trong phong thủy, đào phú quý còn được xem là loài hoa mang lại may mắn, xua đuổi tà khí, mang đến năng lượng tích cực cho không gian sống và làm việc.\r\n\r\n',180000.00,10,'uploads/products/1742650388233_hoa Đào Phú Quý.jpg',1,'2025-03-04 10:25:00','2025-03-22 21:08:57'),(61,'Hoa Mai Vàng','Hoa mai vàng là loài hoa truyền thống, gắn liền với hình ảnh ngày Tết cổ truyền của người Việt, đặc biệt là ở miền Nam. Những cánh mai mỏng manh, vàng rực như ánh nắng đầu xuân tượng trưng cho phú quý, tài lộc, may mắn và sự khởi đầu mới đầy hy vọng.\r\n\r\nMai vàng thường nở rộ vào dịp xuân, mang lại không khí ấm áp, vui tươi và tràn đầy năng lượng. Với vẻ đẹp thanh thoát và ý nghĩa sâu sắc, hoa mai không chỉ là vật trang trí ngày Tết mà còn là lời chúc bình an, phát đạt gửi đến người thân, bạn bè và đối tác.\r\n\r\n',250000.00,12,'uploads/products/1742650038535_Mai Vàng Tết.jpg',1,'2025-03-04 10:30:00','2025-03-22 21:08:26'),(62,'Hoa Tulip Đỏ','Hoa tulip đỏ là biểu tượng nổi bật của tình yêu nồng nàn và đam mê sâu sắc. Với hình dáng thanh lịch, cánh hoa mượt mà và sắc đỏ rực rỡ, tulip đỏ luôn tạo ấn tượng mạnh mẽ ngay từ ánh nhìn đầu tiên.\r\n\r\nLoài hoa này thường được lựa chọn trong các dịp đặc biệt như lễ tình nhân, cầu hôn hoặc chúc mừng tình yêu, bởi ý nghĩa sâu sắc về sự chân thành, tình cảm mãnh liệt và sự tôn trọng trong mối quan hệ. Không chỉ đẹp về màu sắc, tulip đỏ còn thể hiện phong cách hiện đại, sang trọng và tinh tế trong các thiết kế hoa nghệ thuật.',320000.00,8,'uploads/products/1742650021233_Tulip Đỏ.jpg',1,'2025-03-04 10:35:00','2025-03-22 21:07:57'),(63,'Hoa Hướng Dương Mặt Trời','Hoa hướng dương, hay còn gọi là hoa mặt trời, là loài hoa nổi bật với bông hoa to, cánh vàng rực rỡ và nhụy tròn nâu đậm, luôn vươn mình hướng về phía ánh sáng mặt trời. Loài hoa này là biểu tượng của niềm tin, hy vọng, sự lạc quan và sức sống mãnh liệt.\r\n\r\nKhông chỉ mang vẻ đẹp tràn đầy năng lượng, hướng dương còn mang ý nghĩa gắn liền với lòng trung thành và sự kiên định trong tình yêu cũng như trong cuộc sống. Hoa thường được sử dụng trong các dịp chúc mừng, khích lệ tinh thần, hoặc trang trí không gian để tạo cảm giác tươi mới, tích cực.',90000.00,25,'uploads/products/1742649995972_hướng dương.jpg',1,'2025-03-04 10:40:00','2025-03-22 21:07:43'),(75,'Hoa Cẩm Chướng','Hoa cẩm chướng là loài hoa mềm mại với những cánh hoa uốn lượn như vân ren, tạo nên vẻ đẹp tinh tế và duyên dáng. Cẩm chướng có nhiều màu sắc phong phú như hồng, đỏ, trắng, tím, vàng – mỗi màu mang một ý nghĩa riêng như tình yêu, sự ngưỡng mộ, lòng biết ơn hay sự thuần khiết.\r\n\r\nLoài hoa này thường xuất hiện trong những dịp lễ kỷ niệm, ngày của mẹ, lễ tốt nghiệp hoặc trong các bó hoa chúc mừng, bởi nó không chỉ đẹp mà còn giàu ý nghĩa nhân văn. Cẩm chướng còn tượng trưng cho tình cảm chân thành và sự bền bỉ trong tình yêu cũng như cuộc sống.\r\n',70000.00,1247,'uploads/products/1742649969566_cẩm chướng.jpg',1,'2025-03-13 11:09:30','2025-03-22 21:07:16'),(76,'Hoa Mẫu Đơn','Hoa mẫu đơn là loài hoa quý phái, nổi bật với những bông hoa lớn, cánh dày, mềm mại và màu sắc rực rỡ như hồng, đỏ, trắng hoặc tím. Từ lâu, mẫu đơn đã được xem là biểu tượng của sự giàu sang, phú quý, sắc đẹp và tình yêu nồng nàn trong nhiều nền văn hóa phương Đông.\r\n\r\nVới hình dáng kiêu sa và hương thơm dịu nhẹ, hoa mẫu đơn thường được sử dụng trong các dịp đặc biệt như cưới hỏi, lễ chúc mừng hoặc trang trí không gian sống để tôn lên vẻ sang trọng và may mắn. Loài hoa này cũng là lựa chọn lý tưởng trong các lẵng hoa nghệ thuật hay thiết kế hoa cao cấp.\r\n\r\n',84000.00,1073,'uploads/products/1742649959505_Mẫu Đơn.jpg',1,'2025-03-13 11:09:30','2025-03-22 21:06:55'),(77,'Hoa Cúc Đại Đóa','Hoa cúc đại đóa là loài hoa nổi bật với những bông hoa lớn, rực rỡ và nhiều lớp cánh xếp đều đặn, tạo nên vẻ đẹp sang trọng và cuốn hút. Cúc đại đóa thường có nhiều màu sắc như vàng, trắng, hồng hoặc đỏ, tượng trưng cho sự trường thọ, may mắn và niềm vui trong cuộc sống.\r\n\r\nLoài hoa này không chỉ được trồng để làm cảnh mà còn được sử dụng trong các dịp lễ Tết, cưới hỏi hoặc trang trí không gian sống. Với vẻ đẹp bền lâu và ý nghĩa tích cực, cúc đại đóa luôn là lựa chọn hàng đầu trong các bó hoa trang trọng hoặc lẵng hoa chúc mừng.\r\n\r\n',70000.00,1637,'uploads/products/1742649682490_Hoa Cúc Đại Đóa.jpg',1,'2025-03-13 11:09:30','2025-03-22 21:06:29'),(79,'Hoa Oải Hương','Hoa oải hương là một loài thực vật có hương thơm dịu nhẹ, nổi bật với những bông hoa màu tím thanh nhã và mùi hương thư giãn. Thuộc họ bạc hà (Lamiaceae), oải hương được yêu thích không chỉ bởi vẻ đẹp mà còn bởi đặc tính làm dịu tinh thần.\r\n\r\nCây thường mọc thành từng cụm nhỏ với những bông hoa li ti màu tím lam thu hút ong và bướm. Oải hương được sử dụng phổ biến trong liệu pháp hương thơm, tinh dầu, nước hoa và thậm chí trong ẩm thực.\r\n\r\nHương thơm nhẹ nhàng của oải hương giúp giảm căng thẳng, cải thiện giấc ngủ và mang lại cảm giác thư giãn. Trong vườn, hoa oải hương được yêu thích bởi vẻ đẹp quyến rũ, mùi hương dễ chịu và khả năng sinh trưởng tốt ở nơi có nắng và đất thoát nước tốt.\r\n\r\n',57500.00,618,'uploads/products/1742649888087_oải hương.jpg',1,'2025-03-13 11:45:09','2025-03-22 21:06:08'),(103,'Hoa Kadupul','Hoa Kadupul chỉ nở vào ban đêm và tàn sau vài giờ. Hương thơm nhẹ nhàng, hình dáng mỏng manh như lụa, thường được xem là loài hoa linh thiêng ở Sri Lanka.',50000.00,20,'uploads/products/1742994294572_Hoa Kadupul.jpg',1,'2025-03-26 20:01:34','2025-03-26 20:06:23'),(104,'Hoa Middlemist’s Red','Middlemist’s Red là một trong những loài hoa hiếm nhất thế giới, chỉ còn tồn tại ở Anh và New Zealand. Cánh hoa đỏ thắm như nhung, dày dặn và đều đặn như hoa mẫu đơn.',100000.00,20,'uploads/products/1742994265621_Middlemist’s.jpg',1,'2025-03-26 20:01:34','2025-03-26 20:06:23'),(105,'Hoa Youtan Poluo','Hoa Youtan Poluo nhỏ như hạt gạo, được cho là xuất hiện mỗi 3000 năm. Hoa trắng, mùi thơm thoang thoảng như gỗ đàn hương, tượng trưng cho sự linh thiêng và thần thoại phương Đông.',125000.00,20,'uploads/products/1742994233147_ylian.jpg',1,'2025-03-26 20:01:34','2025-03-26 20:06:23'),(106,'Hoa Juliet Rose','Juliet Rose là giống hoa hồng được lai tạo trong 15 năm, nổi bật với màu đào nhẹ nhàng và mùi thơm ngọt ngào như trái cây, được mệnh danh là loài hoa đắt nhất thế giới.',200000.00,20,'uploads/products/1742994197689_Rose Juliet.jpg',1,'2025-03-26 20:01:34','2025-03-26 20:06:23'),(107,'Hoa Ghost Orchid','Ghost Orchid không có lá, sống ký sinh trên các loài cây khác ở vùng đầm lầy Florida. Hoa có hình dáng kỳ lạ như bóng ma đang trôi lơ lửng và rất khó trồng nhân tạo.',150000.00,19,'uploads/products/1742994169489_flower Wallpaper aesthetic.jpg',1,'2025-03-26 20:01:34','2025-03-27 00:11:37');
